run:
() => {
      const C = window.carsi, out = [];
      for (let i = 0; i < 10; i++) {
        C.build(i); C.sim(240);
        out.push({ end: C.mode, t: +C.time.toFixed(2), lok: C.lokum, falls: C.falls, stars: C.stars.filter(Boolean).length, top: C.stalls.toppled });
      }
      window.__gateOut = out;
    }
